import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
import {createProfileToken,handleProfilePage} from './profile-page.ts';
import {beginKleinanzeigenLogin,completeKleinanzeigenLogin,completeKleinanzeigenCallback,checkKleinanzeigenConnection,disconnectKleinanzeigen,inspectKleinanzeigenInquiry,type KleinanzeigenOAuthConfig} from './providers/kleinanzeigen.ts';
import {checkImmoScoutConnection,disconnectImmoScout,inspectImmoScoutInquiry} from './providers/immoscout.ts';
import {checkImmoweltConnection,disconnectImmowelt} from './providers/immowelt.ts';
import {probeImmomioApplication} from './providers/immomio.ts';
import {providerForListing,sendApplication,providerAttachmentCapability} from './providers/router.ts';
import {getCentralImmoScoutConnection,markConnection} from './credentials.ts';
import {applicationMessageFor,profileAdapterSelfTest} from '../_shared/application-profile-adapters.ts';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const base=Deno.env.get('SUPABASE_URL')!;
const PACKAGE_ENDPOINT=`${base}/functions/v1/application-package`;
const KLEIN_OAUTH_REDIRECT='https://login.traumwohnunghamburg.de/connect/kleinanzeigen/callback';
const KLEIN_BETA_DIRECT_REDIRECT=`${base}/functions/v1/application-worker?oauth=kleinanzeigen`;
const KLEIN_LEGACY_CLIENT_ID='uV5j90myVPc2XzEOFuWUD2At17OACEGQ';
const TELEGRAM_CONNECTED='https://t.me/traumwohnunghamburgbot?start=ka_connected';
const TELEGRAM_FAILED='https://t.me/traumwohnunghamburgbot?start=ka_failed';
const TELEGRAM_PENDING='https://t.me/traumwohnunghamburgbot?start=ka_oauth_pending';

async function secret(name:string){const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data);}
async function optionalSecret(name:string){try{const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)return null;return String(data);}catch{return null;}}
async function eligible(userId:string){const {data,error}=await db.rpc('application_user_eligible',{p_user:userId});if(error||data!==true)throw Error('premium_required');}
async function setPersonalImmoScoutTestMode(userId:string,telegramUserId:number,enabled:boolean){
 const {data:user,error:userError}=await db.from('bot_users')
  .select('id,telegram_user_id,is_active,auto_apply_enabled,test_auto_apply_allowed')
  .eq('id',userId).maybeSingle();
 if(userError||!user||Number(user.telegram_user_id)!==telegramUserId||user.test_auto_apply_allowed!==true||!user.is_active)throw Error('test_mode_forbidden');

 if(enabled){
  if(user.auto_apply_enabled===true)throw Error('test_mode_global_auto_apply_active');
  await eligible(userId);

  const {data:missing,error:missingError}=await db.rpc('application_profile_missing_fields',{p_user:userId});
  if(missingError||(Array.isArray(missing)&&missing.length))throw Error('test_mode_profile_incomplete');

  const {data:searchProfiles,error:searchError}=await db.from('search_profiles')
   .select('id').eq('user_id',userId).or('is_active.eq.true,is_active.is.null').limit(1);
  if(searchError)throw Error('test_mode_search_profile_missing');
  if(!searchProfiles?.length)throw Error('test_mode_search_profile_missing');

  let central:any=null;
  try{central=await getCentralImmoScoutConnection(db);}catch{}
  if(!central
    ||central.row?.status!=='connected'
    ||central.row?.enabled!==false
    ||String(central.row?.account_hint||'').trim().toLowerCase()!=='arash@nexalabs.de'
    ||!central.credentials?.refresh_token){
   throw Error('test_mode_central_account_unavailable');
  }
 }

 const {data,error}=await db.rpc('set_application_test_mode',{
  p_user:userId,
  p_telegram_user_id:telegramUserId,
  p_enabled:enabled
 });
 if(error){
  const message=String(error.message||'');
  if(message.includes('test_mode_forbidden'))throw Error('test_mode_forbidden');
  if(message.includes('test_mode_global_auto_apply_active'))throw Error('test_mode_global_auto_apply_active');
  if(message.includes('test_mode_profile_incomplete'))throw Error('test_mode_profile_incomplete');
  if(message.includes('test_mode_search_profile_missing'))throw Error('test_mode_search_profile_missing');
  throw Error('test_mode_update_failed');
 }
 return data||{enabled};
}
const uuid=(v:any)=>{const s=String(v||'');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s))throw Error('invalid_user');return s;};
const clean=(v:any,max=4000)=>String(v||'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
const randomTicket=(bytes=32)=>{const a=crypto.getRandomValues(new Uint8Array(bytes));let s='';for(const b of a)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');};
async function beginImmoweltLogin(userId:string,body:any){
 const origin=clean(body?.origin,40)||'telegram',returnTarget=clean(body?.returnTarget,40)||'telegram';
 const issuedBy=origin==='coach'?uuid(body?.issuedBy):null,state=randomTicket(32);
 await db.from('platform_auth_flows').update({consumed_at:new Date().toISOString()}).eq('user_id',userId).eq('provider','immowelt').is('consumed_at',null);
 const {error}=await db.from('platform_auth_flows').insert({
  user_id:userId,provider:'immowelt',state,code_verifier:null,origin,issued_by:issuedBy,return_target:returnTarget,
  context:body?.context&&typeof body.context==='object'?body.context:{}
 });
 if(error)throw Error('auth_flow_create_failed');
 return{status:'login',url:`https://login.traumwohnunghamburg.de/connect?ticket=${encodeURIComponent(state)}`,expiresInSeconds:1800,directProvider:true,shareFlow:false,transport:'credential-session'};
}

const STATUS_SYNC_ENDPOINT=`${base}/functions/v1/notification-dispatcher`;
async function syncListingStatus(userId:string,listingId:string){try{const internal=await secret('internal_worker_secret');await fetch(STATUS_SYNC_ENDPOINT,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action:'sync_application_status',userId,listingId}),signal:AbortSignal.timeout(15000)});}catch{}}
async function kleinanzeigenOAuthConfig():Promise<KleinanzeigenOAuthConfig|null>{const clientId=await optionalSecret('kleinanzeigen_oauth_client_id');if(!clientId)return null;return {clientId,redirectUri:KLEIN_OAUTH_REDIRECT};}
function betaKleinanzeigenOAuthConfig():KleinanzeigenOAuthConfig{return{clientId:KLEIN_LEGACY_CLIENT_ID,redirectUri:KLEIN_BETA_DIRECT_REDIRECT};}
async function messageWithDocuments(userId:string,applicationId:string,provider:string,baseMessage:string){
 if(!['immoscout','kleinanzeigen'].includes(provider))return{message:baseMessage,documentCount:0,packageUrl:null};
 const {count,error}=await db.from('applicant_documents').select('id',{count:'exact',head:true}).eq('user_id',userId).eq('send_with_auto_apply',true);
 if(error)throw Error('application_documents_read_failed');
 if(!count)return{message:baseMessage,documentCount:0,packageUrl:null};
 const internal=await secret('internal_worker_secret');
 let response:Response,data:any=null;
 try{
  response=await fetch(PACKAGE_ENDPOINT,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action:'create',userId,applicationId}),signal:AbortSignal.timeout(15000)});
  data=await response.json().catch(()=>null);
 }catch{throw Error('document_transfer_failed')}
 if(!response.ok||!data?.url)throw Error('document_transfer_failed');
 const suffix='\n\nBewerbungsunterlagen (geschützter Link): '+String(data.url);
 const base=String(baseMessage||'');
 if(base.length+suffix.length>4000)return{message:base,documentCount:0,packageUrl:null};
 return{message:base+suffix,documentCount:Number(data.count||count),packageUrl:String(data.url)};
}
async function notify(chatId:any,text:string,html=false,replyMarkup:any=null){if(!chatId)return;try{const token=await secret('telegram_bot_token_runtime');await fetch(`https://api.telegram.org/bot${token}/sendMessage`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({chat_id:chatId,text,...(html?{parse_mode:'HTML'}:{}),...(replyMarkup?{reply_markup:replyMarkup}:{})})});}catch{}}
async function notifyUser(userId:string,text:string,html=false){const {data}=await db.from('bot_users').select('chat_id').eq('id',userId).maybeSingle();if(data?.chat_id)await notify(data.chat_id,text,html);}
async function notifyCallbackFailure(callbackUrl:string,errorCode:string){try{const state=new URL(callbackUrl).searchParams.get('state');if(!state)return;const {data:flow}=await db.from('platform_auth_flows').select('user_id').eq('provider','kleinanzeigen').eq('state',state).is('consumed_at',null).maybeSingle();if(!flow?.user_id)return;await markConnection(db,String(flow.user_id),'kleinanzeigen','needs_login',errorCode.slice(0,120)).catch(()=>{});await notifyUser(String(flow.user_id),'⚠️ Kleinanzeigen konnte nicht verbunden werden. Bitte den Login erneut starten.');}catch{}}
async function kleinanzeigenCallbackTarget(callbackUrl:string){try{const state=new URL(callbackUrl).searchParams.get('state');if(!state)return null;const{data}=await db.from('platform_auth_flows').select('origin,return_target,context').eq('provider','kleinanzeigen').eq('state',state).is('consumed_at',null).maybeSingle();return data||null}catch{return null}}
function coachOAuthResult(ok:boolean){const title=ok?'Kleinanzeigen verbunden':'Kleinanzeigen-Verbindung fehlgeschlagen',message=ok?'Die Verbindung wurde gespeichert. Dieses Fenster kann geschlossen werden.':'Die Verbindung konnte nicht abgeschlossen werden. Bitte im Coach Portal erneut starten.',event=ok?'connected':'failed';return new Response(`<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title></head><body style="font-family:system-ui,-apple-system,sans-serif;padding:32px"><h1>${title}</h1><p>${message}</p><p><a href="https://intern.traumwohnunghamburg.de">Zum Coach Portal</a></p><script>try{window.opener&&window.opener.postMessage({type:'tw-provider-oauth',provider:'kleinanzeigen',status:'${event}'},'https://intern.traumwohnunghamburg.de')}catch{};if(${ok?'true':'false'})setTimeout(()=>window.close(),250);</script></body></html>`,{status:ok?200:400,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','content-security-policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'"}})}
async function handleKleinanzeigenOAuthCallback(request:Request){
 const incoming=new URL(request.url),target=await kleinanzeigenCallbackTarget(request.url),coach=target?.return_target==='coach'||target?.origin==='coach',beta=target?.context?.beta_direct_callback===true,config=beta?betaKleinanzeigenOAuthConfig():await kleinanzeigenOAuthConfig();
 if(!config)return coach?coachOAuthResult(false):Response.redirect(TELEGRAM_PENDING,303);
 const callbackUrl=beta?request.url:(()=>{const u=new URL(KLEIN_OAUTH_REDIRECT);for(const [key,value]of incoming.searchParams.entries())if(key!=='oauth')u.searchParams.append(key,value);return u.href})();
 try{
  const result=await completeKleinanzeigenCallback(db,callbackUrl,config);
  if(coach)return coachOAuthResult(true);
  await notifyUser(result.userId,'✅ <b>Kleinanzeigen verbunden</b>\n\nDein Konto wurde erfolgreich verbunden.',true);
  return Response.redirect(TELEGRAM_CONNECTED,303);
 }catch(error:any){
  const code=String(error?.message||'oauth_callback_failed');
  await notifyCallbackFailure(callbackUrl,code);
  return coach?coachOAuthResult(false):Response.redirect(TELEGRAM_FAILED,303);
 }
}
async function processApplication(){const {data:claimed,error:claimError}=await db.rpc('claim_application');if(claimError)throw Error('application_claim_failed');if(!claimed?.length)return {status:'idle'};const application=claimed[0];let started=false,activeListing:any=null,activeProvider:string|null=null,testModeEnabled=false;const patch=async(value:any)=>{const {data,error}=await db.from('applications').update(value).eq('id',application.id).eq('lease_token',application.lease_token).select('id');if(error||!data?.length)throw Error('application_lease_lost');};try{await eligible(application.user_id);const [{data:user,error:userError},{data:listing,error:listingError},{data:profile,error:profileError}]=await Promise.all([db.from('bot_users').select('id,chat_id,is_active,auto_apply_enabled,test_auto_apply_allowed,test_auto_apply_enabled,test_auto_apply_daily_limit').eq('id',application.user_id).single(),db.from('listings').select('id,source_id,canonical_url,title,is_active,raw,external_id,source_listing_key,property_type,property_kind,offer_mode').eq('id',application.listing_id).single(),db.from('applicant_profiles').select('*').eq('user_id',application.user_id).single()]);if(userError||listingError||profileError)throw Error('application_read_failed');activeListing=listing;testModeEnabled=user.test_auto_apply_allowed===true&&user.test_auto_apply_enabled===true&&user.auto_apply_enabled!==true;const immoweltCanary=Number(listing.source_id)===3&&application?.provider_state?.immowelt_canary===true;if((!user.auto_apply_enabled&&!testModeEnabled&&!immoweltCanary)||!user.is_active||!listing.is_active){await patch({status:'failed',last_error:'not_eligible',wait_reason:null,lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return {status:'failed'};}const provider=providerForListing(listing);if(!provider){await patch({status:'failed',last_error:'provider_unsupported',lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return {status:'failed'};}activeProvider=provider;if(testModeEnabled&&provider!=='immoscout'){await patch({status:'failed',last_error:'test_mode_provider_blocked',provider_state:{...application.provider_state,test_mode:true,provider},wait_reason:null,lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return{status:'failed',provider,error:'test_mode_provider_blocked'};}const selectedMessage=provider==='immomio'?null:applicationMessageFor(profile,listing),baseMessage=selectedMessage?.message??null;if(provider!=='immomio'&&!baseMessage){await patch({status:'manual_required',last_error:'application_template_missing',provider_state:{provider,...(testModeEnabled?{test_mode:true}:{}),requiredMessageField:selectedMessage?.field||null},lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return{status:'manual_required',provider,error:'application_template_missing',requiredMessageField:selectedMessage?.field||null};}const transferred=provider==='immomio'?{message:null,documentCount:0,packageUrl:null}:await messageWithDocuments(String(application.user_id),String(application.id),provider,String(baseMessage)),message=transferred.message,attachmentCapability=providerAttachmentCapability(provider);let documents:any[]=[];if(attachmentCapability.supported){const {data:documentRows,error:documentError}=await db.from('applicant_documents').select('id,document_type,storage_path,original_filename,mime_type,size_bytes').eq('user_id',application.user_id).eq('send_with_auto_apply',true);if(documentError)throw Error('application_documents_read_failed');documents=documentRows||[];}await patch({application_text:provider==='immomio'?null:message});const authorize=async()=>{if(immoweltCanary&&provider==='immowelt'){const now=new Date().toISOString(),{data:updated,error:updateError}=await db.from('applications').update({status:'processing',submission_started_at:now,attempts:Number(application.attempts||0)+1,wait_reason:null}).eq('id',application.id).eq('lease_token',application.lease_token).eq('status','pending').is('submission_started_at',null).select('id');if(updateError){started=true;throw Error('authorization_unconfirmed');}started=!!updated?.length;return started;}const {data,error}=await db.rpc('authorize_application_send',{p_id:application.id,p_token:application.lease_token});if(error){started=true;throw Error('authorization_unconfirmed');}started=data===true;return started;};const sendInput:any={db,user,profile,listing,authorize,documents,attachmentCapability,applicationId:String(application.id),leaseToken:String(application.lease_token),immoweltCanary};if(provider!=='immomio')sendInput.message=message;const result=await sendApplication(provider,sendInput);
 if(result?.error==='send_not_authorized'){
  const {data:gate}=await db.from('applications').select('status,wait_reason,next_attempt_at').eq('id',application.id).eq('lease_token',application.lease_token).maybeSingle();
  if(gate?.status==='pending'&&gate?.wait_reason){await patch({lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return {status:'deferred',provider,reason:gate.wait_reason,nextAttemptAt:gate.next_attempt_at};}
 }
 if(result?.error==='listing_unavailable'){await db.from('listings').update({is_active:false}).eq('id',listing.id);}await patch({status:result.status,last_error:result.error||null,provider_state:{provider,...(testModeEnabled?{test_mode:true}:{}),confirmation:result?.confirmation||null,...(result?.diagnostic?{diagnostic:result.diagnostic}:{})},...(result.status==='sent'?{sent_at:new Date().toISOString()}:{}),lease_until:null});await syncListingStatus(String(application.user_id),String(listing.id));return {status:result.status,provider,error:result.error||null};}catch(error:any){const retry=!started&&['temporary_network_error','TimeoutError'].includes(error?.name==='TimeoutError'?'TimeoutError':error?.message)&&Number(application.attempts||0)<2,terminalStatus=started?'manual_required':retry?'pending':'failed';const finalError=started?'submission_unconfirmed':retry?'temporary_network_error':String(error?.message||'application_preparation_failed').slice(0,120);await patch({status:terminalStatus,last_error:finalError,provider_state:{...application.provider_state,...(activeProvider?{provider:activeProvider}:{}),...(testModeEnabled?{test_mode:true}:{})},...(retry?{attempts:Number(application.attempts||0)+1}:{}),next_attempt_at:retry?new Date(Date.now()+60000*(Number(application.attempts||0)+1)).toISOString():null,lease_until:null});if(activeListing)await syncListingStatus(String(application.user_id),String(activeListing.id));return {status:terminalStatus};}}
async function action(body:any){
 if(body.action==='authorize_immowelt_transport'){
  const applicationId=uuid(body.applicationId),leaseToken=uuid(body.leaseToken),now=new Date().toISOString();
  const{data:application,error:applicationError}=await db.from('applications').select('id,user_id,listing_id,status,attempts,submission_started_at,lease_token,lease_until,provider_state').eq('id',applicationId).maybeSingle();
  if(applicationError||!application)return{authorized:false,reason:'application_not_found'};
  if(String(application.lease_token||'')!==leaseToken||application.status!=='pending'||application.submission_started_at||!application.lease_until||String(application.lease_until)<=now)return{authorized:false,reason:'lease_invalid'};
  const{data:listing,error:listingError}=await db.from('listings').select('id,source_id,canonical_url,raw').eq('id',application.listing_id).maybeSingle();
  if(listingError||!listing||providerForListing(listing)!=='immowelt')return{authorized:false,reason:'provider_mismatch'};
  if(application?.provider_state?.immowelt_canary===true){
   await eligible(String(application.user_id));
   const{data:updated,error:updateError}=await db.from('applications').update({status:'processing',submission_started_at:now,attempts:Number(application.attempts||0)+1,wait_reason:null}).eq('id',applicationId).eq('lease_token',leaseToken).eq('status','pending').is('submission_started_at',null).select('id');
   if(updateError||!updated?.length)return{authorized:false,reason:'lease_lost'};
   return{authorized:true,canary:true};
  }
  const{data,error}=await db.rpc('authorize_application_send',{p_id:applicationId,p_token:leaseToken});
  if(error)return{authorized:false,reason:'authorization_failed'};
  return{authorized:data===true,canary:false};
 }
 const userId=uuid(body.userId);if(body.action==='set_test_mode'){const telegramUserId=Number(body.telegramUserId);if(!Number.isSafeInteger(telegramUserId)||telegramUserId<=0)throw Error('test_mode_forbidden');return setPersonalImmoScoutTestMode(userId,telegramUserId,body.enabled===true);}const source=Number(body.source);if(body.action==='complete_shared_login'){if(source===2)return completeKleinanzeigenCallback(db,clean(body.callbackUrl,8000));}if(body.action!=='disconnect')await eligible(userId);if(body.action==='profile_link'){const token=await createProfileToken(db,userId);return {url:`${base}/functions/v1/application-worker?token=${encodeURIComponent(token)}`};}if(body.action==='login_share'){if(source===2){const origin=clean(body.origin,40)||null,issuedBy=origin==='coach'?uuid(body.issuedBy):null,context={...(body.context&&typeof body.context==='object'?body.context:{}),share_flow:true};const result=await beginKleinanzeigenLogin(db,userId,null,{origin,returnTarget:clean(body.returnTarget,40)||null,issuedBy,reuseWindowMs:180000,context});return{...result,requiresCallback:true,automaticCallback:false,bridgeRequired:true,transport:'telegram-share'};}}if(body.action==='login_beta_direct'){if(source===2){const origin=clean(body.origin,40)||null,issuedBy=origin==='coach'?uuid(body.issuedBy):null,context={...(body.context&&typeof body.context==='object'?body.context:{}),beta_direct_callback:true};const result=await beginKleinanzeigenLogin(db,userId,betaKleinanzeigenOAuthConfig(),{origin,returnTarget:clean(body.returnTarget,40)||null,issuedBy,context});return{...result,requiresCallback:false,automaticCallback:true,bridgeRequired:false,transport:'beta-direct-callback'};}}if(body.action==='login_beta_bridge'){if(source===2){const origin=clean(body.origin,40)||null,issuedBy=origin==='coach'?uuid(body.issuedBy):null;const result=await beginKleinanzeigenLogin(db,userId,null,{origin,returnTarget:clean(body.returnTarget,40)||null,issuedBy,reuseWindowMs:180000,context:body.context&&typeof body.context==='object'?body.context:{}});const ticket=(()=>{try{return new URL(String(result.url||'')).searchParams.get('state')||''}catch{return''}})();if(!ticket)throw Error('auth_flow_create_failed');return{...result,ticket,requiresCallback:false,automaticCallback:true,bridgeRequired:false,transport:'remote-browser-handoff'};}}if(body.action==='login'){if(source===4)return beginImmoweltLogin(userId,body);if(source===2){const config=await kleinanzeigenOAuthConfig();if(!config)throw Error('oauth_client_not_provisioned');const origin=clean(body.origin,40)||null,issuedBy=origin==='coach'?uuid(body.issuedBy):null;return beginKleinanzeigenLogin(db,userId,config,{origin,returnTarget:clean(body.returnTarget,40)||null,issuedBy,context:body.context&&typeof body.context==='object'?body.context:{}});}if(source===1)return {status:'blocked',error:'provider_contract_unverified',officialApiRequired:false};}if(body.action==='complete_login'){if(source===2)return completeKleinanzeigenLogin(db,userId,clean(body.callbackUrl,8000));}if(body.action==='check'){if(source===4)return checkImmoweltConnection(db,userId);if(source===2)return checkKleinanzeigenConnection(db,userId);if(source===1)return checkImmoScoutConnection(db,userId);}if(body.action==='disconnect'){if(source===4)return disconnectImmowelt(db,userId);if(source===2)return disconnectKleinanzeigen(db,userId);if(source===1)return disconnectImmoScout(db,userId);}if(body.action==='probe_immoscout'){
 const listingId=uuid(body.listingId);
 const [{data:user,error:userError},{data:listing,error:listingError},{data:profile,error:profileError}]=await Promise.all([
  db.from('bot_users').select('id,chat_id,is_active,auto_apply_enabled').eq('id',userId).single(),
  db.from('listings').select('id,source_id,canonical_url,title,is_active,raw,external_id,source_listing_key,property_type,property_kind,offer_mode').eq('id',listingId).single(),
  db.from('applicant_profiles').select('*').eq('user_id',userId).single()
 ]);
